import Foundation

enum Sampling: String, Hashable { case full = "444", horizontal = "422", both = "420"
    var factors: (Int, Int) { switch self { case .full: return (1, 1); case .horizontal: return (2, 1); case .both: return (2, 2) } }
}
enum HuffmanMode: String, Hashable { case standard, optimized }
struct Settings { var qualities: [Int] = []; var sampling = Sampling.full; var restartInterval = 0; var mode = HuffmanMode.standard; var targetBytes = 0; var generations = 0; var truncations: [Int] = [] }
struct Tables { let transform: Plane; let quantization: [Plane]; let huffman: [TableKey: HuffmanTable] }
func inputLines(_ name: String) throws -> [String] { try String(contentsOfFile: "input/" + name, encoding: .ascii).split(separator: "\n").map(String.init) }
func readPPM(_ name: String) throws -> RGBImage { let lines = try inputLines(name), width = Int(lines[1].split(separator: " ")[0])!; return lines.dropFirst(3).map { line in let values = line.split(separator: " ").map { Int($0)! }; return (0..<width).map { RGB(red: values[3 * $0], green: values[3 * $0 + 1], blue: values[3 * $0 + 2]) } } }
func writePPM(_ name: String, _ image: RGBImage) throws { let lines = ["P3", "\(image[0].count) \(image.count)", "255"] + image.map { row in row.flatMap { [String($0.red), String($0.green), String($0.blue)] }.joined(separator: " ") }; try (lines.joined(separator: "\n") + "\n").write(toFile: "output/" + name, atomically: false, encoding: .ascii) }
func readParameters() throws -> Settings { var settings = Settings(); for line in try inputLines("params.txt") { let fields = line.split(separator: " ").map(String.init); switch fields[0] { case "qualities": settings.qualities = fields.dropFirst().map { Int($0)! }; case "sampling": settings.sampling = Sampling(rawValue: fields[1])!; case "restart_interval": settings.restartInterval = Int(fields[1])!; case "huffman": settings.mode = HuffmanMode(rawValue: fields[1])!; case "target_bytes": settings.targetBytes = Int(fields[1])!; case "generations": settings.generations = Int(fields[1])!; default: settings.truncations = fields.dropFirst().map { Int($0)! } } }; return settings }
func readTables() throws -> Tables { let lines = try inputLines("tables.txt"), transform = lines[1...8].map { $0.split(separator: " ").map { Int($0)! } }, quantization = [lines[10...17].map { $0.split(separator: " ").map { Int($0)! } }, lines[19...26].map { $0.split(separator: " ").map { Int($0)! } }]; var huffman: [TableKey: HuffmanTable] = [:]; for start in stride(from: 27, to: 39, by: 3) { let fields = lines[start].split(separator: " "), key = TableKey(kind: Int(fields[1])!, id: Int(fields[2])!); huffman[key] = HuffmanTable(lines[start + 1].split(separator: " ").map { Int($0)! }, lines[start + 2].split(separator: " ").map { Int($0)! }) }; return Tables(transform: transform, quantization: quantization, huffman: huffman) }
func readHex(_ name: String) throws -> [Int] { let bytes = Array(try inputLines(name).joined().utf8); func digit(_ value: UInt8) -> Int { Int(value <= 57 ? value - 48 : value - 87) }; return stride(from: 0, to: bytes.count, by: 2).map { digit(bytes[$0]) * 16 + digit(bytes[$0 + 1]) } }
func hexByte(_ value: Int) -> String { let text = String(value, radix: 16); return text.count == 1 ? "0" + text : text }
func writeHex(_ name: String, _ bytes: [Int]) throws { let lines = stride(from: 0, to: bytes.count, by: 32).map { start in bytes[start..<min(start + 32, bytes.count)].map { hexByte($0) }.joined() }; try (lines.joined(separator: "\n") + "\n").write(toFile: "output/" + name, atomically: false, encoding: .ascii) }
